preConditionHook:
// TAKE PROFIT AT A PRIOR SWING PIVOT -- a STRUCTURAL target, where the rest of
// the catalog's targets are dollar or ATR distances. A long is closed when the
// bar's high reaches the pivotIndex-th most recent confirmed swing high; a
// short when the bar's low reaches the pivotIndex-th most recent swing low.
//
// One rule at two book indices, not two rules: R05-21 targets the top of the
// wedge's SECOND push (pivotIndex 2, and its further target, the bottom of the
// wedge, is the same rule at a deeper index) and V06-02 the expanding
// triangle's most recent opposing pivot (pivotIndex 1, the default).
// Measured-move targets are a different mechanism and live in exits_targets.
//
// THE -1 SENTINEL is the whole hazard here. A window with no pivot leaves the
// level at -1, which sits BELOW every real price, so an unguarded long target
// would be reached on the entry bar and the position closed at once.
// haveTargetHi / haveTargetLo are that guard, and the level is trusted only
// once the scan has actually found pivotIndex pivots.
//
// Pivot scan as in ThreePushPattern, inlined; the register lists Occurrence 3+
// as unmeasured, so the deeper indices are found by hand rather than by a
// third-occurrence call. MEASURED (EL_Swing_Probe.txt / el_swing_output1.txt,
// @ES 60 min): the pivot bar is AT OR ABOVE the swingStrength OLDER bars and
// STRICTLY ABOVE the swingStrength NEWER bars -- bars-ago indexing, so the
// newer bars are the smaller k and take el_gt / el_lt, the older el_ge /
// el_le; confirmation lag exactly swingStrength bars; candidate offsets
// swingStrength .. lookbackBars - 1, the neighbourhood reaching swingStrength
// bars past the window, so the deepest bar touched is
// lookbackBars - 1 + swingStrength. pivotIndex is clamped to the three pivots
// the scan keeps. No early break, matching the twin.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)swingStrength;
pivWindow = (int)lookbackBars;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiPx1 = high[j];
        if (nHiPiv == 2) hiPx2 = high[j];
        if (nHiPiv == 3) hiPx3 = high[j];
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loPx1 = low[j];
        if (nLoPiv == 2) loPx2 = low[j];
        if (nLoPiv == 3) loPx3 = low[j];
    }
}
needP = (int)pivotIndex;
if (needP < 1) needP = 1;
if (needP > 3) needP = 3;
targetHi = hiPx3;
targetLo = loPx3;
if (needP == 1) { targetHi = hiPx1; targetLo = loPx1; }
if (needP == 2) { targetHi = hiPx2; targetLo = loPx2; }
haveTargetHi = (nHiPiv >= needP);
haveTargetLo = (nLoPiv >= needP);
// toleranceAtr LETS THE TARGET BE TAKEN JUST SHORT OF THE PIVOT (added in the
// final review in place of a separate PriorSwingExtremeTarget rule, and the
// same spelling ChannelLineTargetExit uses): the long target becomes
// targetHi - toleranceAtr * ATR and the short target targetLo + toleranceAtr *
// ATR. At the default 0 the test is exactly "reaches the pivot" and the rule is
// unchanged, so no existing placement moves.
//
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and updated
// thereafter as TWO statements -- EL evaluates S[1] + in - out left to right,
// and folding it to S += in - out rounds differently.
// The local counter is atrLen, not atrLength: atrLength is this rule's INPUT.
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLength;
